CREATE TABLE `TrainerPhone` (`id` VARCHAR(191) NOT NULL, `globalTenantId` VARCHAR(191) NOT NULL, `label` VARCHAR(191) NOT NULL, `phone` VARCHAR(191) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `TrainerPhone_globalTenantId_phone_key` (`globalTenantId`,`phone`), INDEX `TrainerPhone_globalTenantId_active_idx` (`globalTenantId`,`active`));
CREATE TABLE `KnowledgeChangeProposal` (`id` VARCHAR(191) NOT NULL, `globalTenantId` VARCHAR(191) NOT NULL, `trainerPhoneId` VARCHAR(191) NOT NULL, `sourceMessageId` VARCHAR(191) NULL, `sourceTranscript` TEXT NULL, `targetKnowledgeId` VARCHAR(191) NULL, `changeType` VARCHAR(191) NOT NULL, `beforeValue` JSON NULL, `proposedValue` JSON NOT NULL, `baseRevision` INTEGER NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'PENDING', `expiresAt` DATETIME(3) NOT NULL, `confirmedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `KnowledgeChangeProposal_globalTenantId_status_createdAt_idx` (`globalTenantId`,`status`,`createdAt`));
CREATE TABLE `KnowledgeRevision` (`id` VARCHAR(191) NOT NULL, `globalTenantId` VARCHAR(191) NOT NULL, `proposalId` VARCHAR(191) NULL, `knowledgeItemId` VARCHAR(191) NULL, `revision` INTEGER NOT NULL, `beforeValue` JSON NULL, `afterValue` JSON NOT NULL, `revertedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `KnowledgeRevision_globalTenantId_revision_key` (`globalTenantId`,`revision`), INDEX `KnowledgeRevision_knowledgeItemId_createdAt_idx` (`knowledgeItemId`,`createdAt`));
CREATE TABLE `KnowledgeCorrection` (`id` VARCHAR(191) NOT NULL, `globalTenantId` VARCHAR(191) NOT NULL, `knowledgeItemId` VARCHAR(191) NOT NULL, `revisionId` VARCHAR(191) NOT NULL, `content` TEXT NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `KnowledgeCorrection_knowledgeItemId_active_idx` (`knowledgeItemId`,`active`));
